import{_ as a,o as s,c as n,S as l}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"Chromebook Pixel (2013) 安装Linux的方法","description":"","frontmatter":{"title":"Chromebook Pixel (2013) 安装Linux的方法","date":"2015-4-20 19:54","comments":true,"archives":2015,"tags":["chrome"]},"headers":[],"relativePath":"posts/2015-04-20-chromebook-pixel-install-linux/index.md","filePath":"posts/2015/2015-05-31-chromebook-pixel-install-linux.md"}'),i={name:"posts/2015-04-20-chromebook-pixel-install-linux/index.md"};function o(r,e,p,t,c,d){return s(),n("div",null,[...e[0]||(e[0]=[l(`<p>同学最近淘了一台二手 Chromebook Pixel (2013)，这款笔记本最大的诱惑就是 12.85 寸但是配备了一块 2560 x 1700 分辨率的触摸屏。上网的体验不要太爽啊，在体验了一小时的 Chrome OS 之后，便感叹就只有一个浏览器而已啊！于是开始折腾如何安装 Linux，毕竟这款笔记本本来就对 Linux 支持很好。下面开始介绍安装过程。</p><p>由于这款笔记本是 x86 架构还自带 SeaBIOS，所以在安装 Linux 上省了不少功夫，很多非 SeaBIOS 的 Chromebook 都是需要刷固件才能引导 Linux 的。</p><h2 id="启用开发者模式" tabindex="-1">启用开发者模式 <a class="header-anchor" href="#启用开发者模式" aria-label="Permalink to &quot;启用开发者模式&quot;">​</a></h2><ul><li>启动电脑</li><li>按住 Esc 和 F3（刷新）按钮，这时候按电源键，即可进入 Recovery 模式</li><li>按 Ctrl+ D，会提示你是否要进入开发者模式，确认之后等一会系统就会转变成启用开发者模式</li></ul><p>这时候每次开机屏幕都有警告提示，要么按 Ctrl + D，或者等待 30s 系统响一声便进入系统。</p><h2 id="进入超级用户-shell" tabindex="-1">进入超级用户 shell <a class="header-anchor" href="#进入超级用户-shell" aria-label="Permalink to &quot;进入超级用户 shell&quot;">​</a></h2><ul><li>按 Ctrl+Alt+F2（→），之后你会看到一个登录提示</li><li>输入 <code>chronos</code> 作为用户名，没有密码</li><li>然后输入 <code>sudo bash</code>,以超级用户使用 shell</li></ul><h2 id="启用-seabios" tabindex="-1">启用 SeaBIOS <a class="header-anchor" href="#启用-seabios" aria-label="Permalink to &quot;启用 SeaBIOS&quot;">​</a></h2><p>在终端里面输入下面的指令：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># crossystem dev_boot_usb=1 dev_boot_legacy=1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>之后重启电脑即可。之后每次进入 SeaBIOS 都要在开机的时候按 Ctrl + L</p><h2 id="将-seabios-设置成默认启动" tabindex="-1">将 SeaBIOS 设置成默认启动 <a class="header-anchor" href="#将-seabios-设置成默认启动" aria-label="Permalink to &quot;将 SeaBIOS 设置成默认启动&quot;">​</a></h2><p>首先你需要破解硬件写保护，按照 wiki 上的说法需要拆机和跳线，具体的操作可以查看这个<a href="https://www.chromium.org/chromium-os/developer-information-for-chrome-os-devices/chromebook-pixel" target="_blank" rel="noreferrer">wiki</a>,拆机操作非常危险，请自己慎重考虑。</p><p>如果你已经成功破解硬件写保护，接下来就是解除软件写保护。同样是进入超级用户 shell 然后输入指令禁用软件写保护：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># flashrom --wp-disable</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>检查软件写保护：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># flashrom --wp-status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>运行 set_gbb_flags.sh ：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># set_gbb_flags.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>注意：新版本的 Chrome OS 已经把这个脚本移动到 <code>/usr/share/vboot/bin/set_gbb_flags.sh</code>位置了，然而并不在$PATH 环境变量中。</p><p>确认有下面的输出：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>GBB_FLAG_DEV_SCREEN_SHORT_DELAY 0x00000001</span></span>
<span class="line"><span>GBB_FLAG_FORCE_DEV_SWITCH_ON 0x00000008</span></span>
<span class="line"><span>GBB_FLAG_FORCE_DEV_BOOT_LEGACY 0x00000080</span></span>
<span class="line"><span>GBB_FLAG_DEFAULT_DEV_BOOT_LEGACY 0x00000400</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>现在可以设置 SeaBIOS 为默认了：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># set_gbb_flags.sh 0x489</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>最后再重新启用写保护：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># flashrom --wp-enable</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>现在可以使用 Linux 安装 U 盘进行安装了。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>插上 U 盘，开机然后按 Ctrl+ L 发现启动光盘正常启动，然后选择安装之后突然提示。。。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>not enough memory to load specified image</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这时候不要慌张，在安装选择菜单点击 Tab 键，可以编辑启动命令，在双横线前面输入 <code>mem=4G</code> 注意是双横线前面！</p><p>恢复 Chrome OS，请参阅<a href="https://support.google.com/chromebook/answer/1080595?hl=en" target="_blank" rel="noreferrer">Recover your Chromebook</a></p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://wiki.archlinux.org/index.php/Chrome_OS_devices" target="_blank" rel="noreferrer">Chrome OS devices</a></p><p><a href="https://wiki.archlinux.org/index.php/Chrome_OS_devices/Chromebook" target="_blank" rel="noreferrer">Chromebook</a></p><p><a href="http://vger.kernel.org/~davem/chromebook_pixel_linux.txt" target="_blank" rel="noreferrer">Installing Linux on the Chromebook Pixel</a></p>`,36)])])}const u=a(i,[["render",o]]);export{h as __pageData,u as default};
